(() => {
 const U=FRTB_UI,{slider,select}=U,R=RISK,money=v=>'£'+v.toLocaleString('en-GB',{maximumFractionDigits:0}),f=v=>v.toLocaleString('en-GB',{maximumFractionDigits:2});
 const instruments={bond:'Corporate bond',swap:'Interest-rate swap',cds:'CDS · protection buyer',equity:'Cash equity',forward:'Equity forward',option:'Equity option',fxoption:'FX option'};
 const definitions=[
  ['dv01','DV01 · the price of a basis point','01 · Rates and credit','How much does one basis point move your value?','rate',['bond','swap','cds'],'bond','A bond is a stream of future cash. A higher discount rate makes those payments worth less today. A receive-fixed swap has a similar direction, while a CDS can behave differently because you are discounting a net protection position.','Change maturity from two to ten years. Does the same rate move have the same price impact?'],
  ['cs01','CS01 · separating credit from rates','01 · Rates and credit','What changes when credit spreads widen?','spread',['bond','cds'],'cds','A credit spread is compensation for bearing credit risk. Widening spreads hurt a bond holder but can help an existing buyer of default protection. Separate the credit move from a change in risk-free discount rates.','Compare a bond holder with a protection buyer. Why do their CS01 signs differ?'],
  ['delta','Delta · the slope of the price','02 · Option sensitivities','How much of the underlying do you effectively own?','spot',['equity','forward','option','fxoption'],'option','Delta is the local slope: how value responds to a tiny underlying move. Cash has a constant slope. An option gradually changes from unlikely to pay into something behaving more like the underlying.','Move spot through the strike, then switch from call to put. What does the slope tell you?'],
  ['gamma','Gamma · a hedge that moves','02 · Option sensitivities','Why does your delta hedge stop fitting?','spot',['option','fxoption','equity','forward'],'option','Gamma measures how the slope itself changes. A delta hedge fits the curve at one point. As spot moves, a curved payoff pulls away from that straight line; the hedge needs updating.','Short the option and shorten its life. What happens near the strike?'],
  ['vega','Vega · the value of uncertainty','02 · Option sensitivities','Why can uncertainty change a price today?','vol',['option','fxoption'],'option','A vanilla option gives its holder a choice: participate in favourable outcomes and walk away from unfavourable exercise. More uncertainty can make that choice more valuable, even when today’s spot price is unchanged.','Hold spot fixed and increase volatility. Then compare a near-expiry option with a longer one.'],
  ['curvature','Curvature · beyond the tangent','03 · From Greeks to capital','What does a large shock reveal that delta misses?','spot',['option','fxoption','bond','swap','cds'],'option','A tangent describes a tiny neighbourhood. Curvature revalues the whole trade after a larger move and removes that tangent effect. Gamma gives a local quadratic estimate; a full shock can cross many different slopes.','Compare a long and short option. Can a convex gain become a positive regulatory curvature loss?']
 ];
 window.FRTB_LESSONS=definitions.map(([id,name,stage,title,factor,allowed,initial,simple,challenge])=>({id,name,stage,title,intro:'Choose an instrument, make a prediction, and compare full revaluation with local approximations.',chart:id==='curvature'?'Full revaluation and the delta you remove':'Exact P&L versus local approximations',simpleTitle:'Think about the shape before the number',simple,challenge,
  inputs:[select('instrument','Instrument',allowed.map(k=>[k,instruments[k]]),initial),select('side','Position direction',[['1','Long / receive fixed / buy protection'],['-1','Short / pay fixed / sell protection']],'1'),slider('size','Notional / reference value',.1,10,.1,1,'£m'),slider('tenor','Time to maturity',1,15,1,5,'years'),slider('expiry','Option expiry',.05,5,.05,1,'years'),slider('rate','Risk-free rate',-1,10,.25,4,'%'),slider('spread','Credit spread',0,1000,25,150,'bp'),slider('coupon','Fixed coupon / CDS premium',0,10,.25,initial==='cds'?1.5:4,'%'),slider('spot','Spot (FX: quoted ×100)',50,150,1,100,''),slider('strike','Strike (FX: quoted ×100)',50,150,1,100,''),slider('vol','Implied volatility',5,80,1,25,'%'),slider('foreign','Foreign interest rate',-1,10,.25,2,'%'),select('put','Option type',[['call','Call'],['put','Put']],'call'),slider('shock','Selected shock',-30,30,1,10,id==='vega'?'vol points':id==='dv01'||id==='cs01'?'×10 bp':'%'),slider('hedge','Underlying delta hedge',0,100,10,0,'%')].map(d=>({...d,when:s=>{
   const opt=['option','fxoption'].includes(s.instrument),credit=['bond','cds'].includes(s.instrument);
   if(d.id==='tenor')return !opt&&s.instrument!=='equity';if(d.id==='expiry')return opt;
   if(['spot','strike'].includes(d.id))return !['bond','swap','cds'].includes(s.instrument)&&(d.id!=='strike'||s.instrument!=='equity');
   if(d.id==='spread')return credit;if(d.id==='coupon')return ['bond','swap','cds'].includes(s.instrument);
   if(['vol','put'].includes(d.id))return opt;if(d.id==='foreign')return s.instrument==='fxoption';
   if(d.id==='hedge')return id==='gamma';return true;
  }})),
  formula:'ΔV ≈ sensitivity × shock + ½ × second derivative × shock²',key:'Positive P&L means a gain. A basis point is 0.01 percentage points. A volatility point is one percentage point, not 1% of the current volatility.',scope:'Synthetic GBP valuations. Bonds and swaps have annual payments, flat continuously compounded rates and integer-year maturities; swap floating PV is 1 − exp(−rT). Bonds discount at rate + spread. CDS uses flat hazard = spread / 60% LGD, continuous payments and fixed 40% recovery. Options use Black–Scholes / Garman–Kohlhagen with constant volatility. Spot 100 is £100 for equity and 1.00 GBP per foreign unit for FX. No smile, curve bootstrap, cash-flow accrual or transaction costs.',
  pages:[],notes:[['Units and signs','We display signed P&L for an upward 1 bp rate or spread move. Some desks quote DV01 / CS01 as a positive loss magnitude; always check the convention. Equity Greeks are for the whole position in displayed spot units. FX price and strike are scaled by 100: sensitivity per actual FX quote unit is 100 times the displayed delta, and gamma 10,000 times.'],['Gamma versus FRTB curvature','Gamma is a local second derivative. CVR± is a loss residual from full up/down revaluation after subtracting the delta effect. The curvature tab uses user-selected shocks to explain the mechanism; those shocks are not prescribed risk weights and the displayed standalone floor is not portfolio SBM capital.']],
  compute(s){const credit=['bond','swap','cds'].includes(s.instrument),key=id==='curvature'?(credit?(s.instrument==='cds'?'spread':'rate'):'spot'):factor;
   const r=R.risk(s,key),scale=key==='spot'?s.spot/100:key==='rate'?.1:key==='spread'?10:1;
   const requested=s.shock*scale,shock=key==='vol'?Math.max(1-s.vol,requested):key==='spread'?Math.max(-s.spread,requested):requested;
   const extent=30,hedge=id==='gamma'?s.hedge/100:0,linear=x=>r.first*x*(1-hedge),full=x=>R.value(s,{[key]:s[key]+x})-r.value-hedge*r.first*x,quadratic=x=>linear(x)+.5*r.second*x*x;
   const data=fn=>Array.from({length:81},(_,i)=>{const x=-extent+2*extent*i/80,dx=x*scale;return [x,fn(key==='vol'?Math.max(1-s.vol,dx):key==='spread'?Math.max(-s.spread,dx):dx)/1000]});
   const actual=full(shock),lin=linear(shock),quad=quadratic(shock),unit=key==='rate'?.01:1,sensitivity=r.first*unit;
   const upShock=Math.abs(shock),downShock=key==='spread'?Math.max(-s.spread,-upShock):key==='vol'?Math.max(1-s.vol,-upShock):-upShock;
   const cu=-(full(upShock)-linear(upShock)),cd=-(full(downShock)-linear(downShock));
   const metric=id==='gamma'?r.second:id==='curvature'?Math.max(0,cu,cd):sensitivity;
   const label={dv01:'Signed DV01 · £ / +1bp',cs01:'Signed CS01 · £ / +1bp',delta:'Position delta · £ / spot unit',gamma:'Position gamma · £ / unit²',vega:'Vega · £ / +1 vol point',curvature:'Toy standalone CVR floor'}[id];
   const rows=[['Current value',money(r.value),'Full model value of the selected position'],['Effective shock',f(shock)+(key==='rate'||key==='vol'?' percentage points':key==='spread'?' bp':' spot units'),'Spread cannot fall below zero; volatility is floored at 1%'],['Exact P&L',money(actual),'Reprice after the selected shock'],['First-order estimate',money(lin),'Initial slope × shock, after any selected hedge'],['Second-order estimate',money(quad),'Add half gamma / second derivative × shock²'],['Nonlinear remainder',money(actual-lin),'Exact P&L minus first-order estimate']];
   if(id==='gamma')rows.push(['Hedge holding',f(-r.first*hedge),'Opposite initial delta; kept fixed during the shock']);
   if(id==='curvature')rows.push(['CVR up',money(cu),'Negative of the up-shock nonlinear remainder'],['CVR down',money(cd),'Negative of the down-shock nonlinear remainder'],['Illustrative standalone loss',money(metric),'max(0, CVR up, CVR down), before any portfolio aggregation']);
   return {stats:[[label,'£'+f(metric)],['Exact shock P&L',money(actual)],['Linear error',money(actual-lin)]],series:[{name:'Exact P&L',data:data(full),color:'#187b64'},{name:'Delta / first order',data:data(linear),color:'#bf904b'},{name:'Second order',data:data(quadratic),color:'#7e75b0'},{name:'Selected shock',data:[[shock/scale,actual/1000]],dots:true,color:'#132f29'}],xlabel:(key==='spot'?'Spot move (%)':key==='vol'?'Volatility move (percentage points)':'Move (multiples of 10 bp)')+' · P&L in £ thousands',headers:['Step','Result','Interpretation'],rows,formula:id==='curvature'?'CVR± = −[V(x ± shock) − V(x) − sensitivity × (±shock)]':id==='dv01'?'Signed DV01 ≈ (∂V/∂r) × 0.0001':id==='cs01'?'Signed CS01 ≈ (∂V/∂spread) × 0.0001':id==='gamma'?'ΔV ≈ Δ × ΔS + ½ Γ × (ΔS)²':id==='vega'?'Vega per vol point ≈ (∂V/∂σ) × 0.01':'ΔV ≈ Δ × ΔS',explanation:`${instruments[s.instrument]}: the effective ${key} move is ${f(shock)} ${key==='rate'||key==='vol'?'percentage points':key==='spread'?'bp':'spot units'}. Full revaluation gives ${money(actual)}, versus ${money(lin)} from the initial slope. ${id==='gamma'&&hedge?`The ${s.hedge}% initial delta hedge removes slope exposure but leaves the curve’s bend. `:''}${id==='curvature'?`The residual becomes a curvature loss only after its sign is reversed: convex gains can produce negative CVR, while a short option can produce positive CVR.`:Math.abs(actual-lin)>1?'The gap shows why a local sensitivity is an approximation, not a promise for a large move.':'Here the straight-line estimate closely tracks the full valuation.'}`,note:'Exact means full revaluation within the displayed simplified model. The point marks your effective shock; floors make extreme negative spread/volatility scenarios flatten.'};
  }
 }));
 window.RISK_APP_CONFIG=true;
})();
